// Hand-written declarations for cities.js, the shared Labs city catalogue generated by
// GitHub/SunApp/update_cities.py. In MeteorWatch index.html does not load it: ts/app.ts adds it
// to the page as a classic script, from the same origin, the first time the person uses the city
// field (loadCatalogue). It defines two globals on globalThis. Never served.

/** One decoded catalogue row. */
interface City {
  /** Display name, for example "Tromso". */
  name: string;
  /** Name folded for search: accents stripped, lower case. */
  fold: string;
  /** Country display name. */
  country: string;
  /** Country name folded the same way as `fold`. */
  cfold: string;
  /** Decimal degrees, north positive. */
  lat: number;
  /** Decimal degrees, east positive. */
  lon: number;
  /** IANA time zone identifier, for example "Europe/Oslo". */
  tz: string;
  /** Folded English exonym where the catalogue stores the local name, otherwise "". */
  alt: string;
}

/** Decoded lazily on first access and cached. */
declare var CITIES: City[];

/** Folds a query the way catalogue names are folded. */
declare function foldQuery(s: string): string;
